import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.BEUshCVJ.js";const g=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1793315481000}'),n={name:"reference/changelog.md"};function s(r,e,l,d,h,c){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to MeetCue. Versions follow <a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><h2 id="_0-3-3-—-2026-10-29" tabindex="-1">0.3.3 — 2026-10-29 <a class="header-anchor" href="#_0-3-3-—-2026-10-29" aria-label="Permalink to &quot;0.3.3 — 2026-10-29&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Knowledge base</strong>: add your résumé, project notes, slides or spreadsheets, and hints build on your real experience. Long files are searched per question on your computer, so each question gets the passages that match it. New formats: Excel, PowerPoint (with speaker notes), OpenDocument, RTF and HTML, and several files can be added at once.</li><li><strong>Try a question</strong> shows which knowledge base passages a question would get.</li><li><strong>Settings › Hints › Prompts</strong> shows the hint model&#39;s instructions and lets you edit them, with warnings for missing placeholders and a button to restore the built-in text.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>A question the speaker pauses in the middle of (&quot;your thoughts on idea A… and idea B&quot;) stays one question: the rest is joined to the same card and the hints are rewritten to cover every part, instead of answering only the first half. This also applies when the early trigger fired at the pause.</li><li>Requests that don&#39;t sound like questions, such as &quot;Talk about…&quot;, &quot;Share a time…&quot; or &quot;谈谈你的看法&quot;, are now recognised.</li><li>Compound questions keep the hints written while detection was still checking them, so their first point arrives about a model round trip sooner.</li><li>Hints lead with a direct answer, cover every part of a compound question in order, read through misheard words, and the sample answer is shorter and easier to say out loud.</li><li>The panel shows only the current question in full, with every other question as one line below it. Click a line to look at that question, and <strong>Back to the current question</strong> returns in one click.</li><li>A question asked before you started answering the previous one becomes the current question instead of waiting as the next one.</li></ul><h2 id="_0-3-2-—-2026-10-29" tabindex="-1">0.3.2 — 2026-10-29 <a class="header-anchor" href="#_0-3-2-—-2026-10-29" aria-label="Permalink to &quot;0.3.2 — 2026-10-29&quot;">​</a></h2><ul><li>macOS 13+ native microphone and system-audio capture, permission guidance, transparent overlays, and app/DMG builds for Apple Silicon and Intel.</li><li>Reuse the macOS speech engine so listing voices does not break subsequent voice previews and mock interviews; reopen audio streams after device failures or sleep.</li></ul><h2 id="_0-3-0-—-2026-10-27" tabindex="-1">0.3.0 — 2026-10-27 <a class="header-anchor" href="#_0-3-0-—-2026-10-27" aria-label="Permalink to &quot;0.3.0 — 2026-10-27&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>The mock interview offers four built-in samples, two in English and two in Chinese: software engineer, network security and AI, backend software engineer (Chinese) and telecom network operations (Chinese, 42 questions in seven groups).</li><li><strong>Go to a question</strong> jumps to any question during a mock interview, forwards or back, from the practice window or the panel&#39;s practice bar.</li><li>Batch changes before a mock interview: tick several questions (Shift-click for a range) to move them to the top or bottom, keep only them, set their group or delete them. The list can be filtered by text or group, and you can add your own questions.</li><li>When Windows has no voice for English or Chinese, the sound check says so and links to the Windows settings that install one, with a step-by-step guide.</li><li><strong>Move</strong> on the panel opens one-click placement for touchpads: snap to any edge or corner (clear of the taskbar), move to the next screen, narrow/normal/wide and ⅓, ½ or full height, opacity, text size, hide for 6 seconds, and let clicks pass through.</li><li><strong>Saved spots</strong>: save up to three panel positions, each with its size and layout, and jump to them with <code>Ctrl+Alt+Shift+1</code>, <code>2</code> and <code>3</code>. On an empty spot the shortcut saves where the panel is now.</li><li><code>Ctrl+Alt+Shift+P</code> hides the panel for 6 seconds so you can click what is behind it; <code>Ctrl+Alt+Shift+T</code> and a tray menu item turn click-through on and off.</li><li><strong>Font</strong> (<strong>Settings › General</strong>) changes the font in every window, and the panel&#39;s text size and opacity can be set there too.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>A double tap and drag on a touchpad, or a double click on the title bar, blew the panel up to cover the whole screen. The panel can now be dragged from any empty part of it and never maximizes.</li><li>A size you drag the panel&#39;s edges to is kept instead of being reset on the next layout change.</li><li>Recording a shortcut with <code>Shift</code> and a digit stored the symbol (<code>!</code>) instead of the digit.</li></ul><h2 id="_0-2-4-—-2026-10-27" tabindex="-1">0.2.4 — 2026-10-27 <a class="header-anchor" href="#_0-2-4-—-2026-10-27" aria-label="Permalink to &quot;0.2.4 — 2026-10-27&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Boost quiet voices from the meeting</strong> (<strong>Settings › Audio</strong>, on by default) raises soft-spoken participants to a normal speaking level before recognition, and system sound has its own, lower voice threshold (−60 dBFS), so quiet questions are no longer missed.</li><li><strong>Write hints while checking the question</strong> (<strong>Settings › Hints</strong>, on by default) starts hint generation together with question detection, so the first point usually appears about a second sooner.</li><li>Hovering over the latency in the panel footer shows how the last hint&#39;s time split between recognition, detection and hints. When hints are slow, the panel names the slowest stage and the setting that helps most.</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><code>MC-SYS-002</code> (&quot;settings folder not writable&quot;) appeared for failures that had nothing to do with the settings folder, such as a window or file dialog that couldn&#39;t open. Those now report <code>MC-SYS-006</code>, and a failed settings save reports <code>MC-SYS-005</code>.</li><li>The check whether the settings folder next to the program is writable could fail for a moment after sign-in or an update and move settings to <code>%APPDATA%\\MeetCue</code>. It now retries, and the notice about it is shown once instead of on every start.</li></ul><h2 id="_0-2-3-—-2026-10-26" tabindex="-1">0.2.3 — 2026-10-26 <a class="header-anchor" href="#_0-2-3-—-2026-10-26" aria-label="Permalink to &quot;0.2.3 — 2026-10-26&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>The mock interview window is a guided four-step flow: a sound check with live level bars, choosing the questions, reviewing them, and practising. Every step says what comes next, and the running step says what is expected of you right now.</li><li><strong>Ask again</strong> reads the current question from the start, in the practice window and on the panel.</li><li>The voice that reads the questions can be chosen per language in the sound check step, with <strong>Try it</strong> to hear it. Reading speed moved there too.</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>A question could stop halfway through: a cough, an &quot;um&quot; or a single word misheard from the question&#39;s own echo counted as the user answering. Interrupting now needs real speech, and filler words from the practice settings never count.</li></ul><h2 id="_0-2-2-—-2026-10-26" tabindex="-1">0.2.2 — 2026-10-26 <a class="header-anchor" href="#_0-2-2-—-2026-10-26" aria-label="Permalink to &quot;0.2.2 — 2026-10-26&quot;">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Mock interviews are easier to start: <strong>Mock interview…</strong> is near the top of the tray menu, the idle panel links to it, and it can be opened from <strong>Settings › General</strong> and from the last step of setup. The window starts with a step-by-step <strong>How it works</strong>.</li><li>Practice playback is now a <strong>Speech-to-text for the questions</strong> switch: on (the default) transcribes the spoken questions exactly like a meeting; off sends their text straight to the hint model. Questions are spoken aloud either way. <strong>Recognise my answers</strong> is now <strong>Speech-to-text for my answers</strong>.</li><li>Built-in sample interviews for software engineering and for network security with AI, as question lists and as interview transcripts, load with one click. Sample job descriptions to use as briefing material are in <code>samples/materials</code>.</li><li>A <a href="/meetcue/guide/mock-interview">mock interview guide</a> explains how to test the whole app over your microphone without a real meeting.</li></ul><h2 id="_0-2-1-—-2026-10-26" tabindex="-1">0.2.1 — 2026-10-26 <a class="header-anchor" href="#_0-2-1-—-2026-10-26" aria-label="Permalink to &quot;0.2.1 — 2026-10-26&quot;">​</a></h2><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>The level meters stopped moving as soon as a meeting or practice session started, in the panel and in <strong>Settings › Audio</strong>, so the microphone looked dead while MeetCue was listening. Practice also missed when you started speaking.</li></ul><h2 id="_0-2-0-—-2026-10-26" tabindex="-1">0.2.0 — 2026-10-26 <a class="header-anchor" href="#_0-2-0-—-2026-10-26" aria-label="Permalink to &quot;0.2.0 — 2026-10-26&quot;">​</a></h2><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Providers and models are entered freely, the same way in setup and in <strong>Settings › Providers &amp; cost</strong>: choose a provider and type any model name for each task. The names a provider reports appear as suggestions; MeetCue no longer lists models or prices, and links to each provider&#39;s official pricing page instead.</li><li>Anthropic can be reached through a gateway or proxy: enter its base URL next to the key. Base URLs are now stored per provider in <code>providers.baseUrls</code>; an existing OpenAI-compatible base URL is kept.</li><li>Prices for budget tracking are entered under <strong>Settings › Providers &amp; cost › Budget › Your own prices</strong>.</li></ul><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Opening <strong>Run setup again</strong>, the activity log or any other window from a button froze MeetCue on Windows: no window could be moved and the app couldn&#39;t be quit.</li><li>Speech recognition: <ul><li>System sound recognition stopped about 20 seconds into a meeting when nothing was playing yet, showing <code>MC-ASR-002</code>. The connection is now kept alive whether or not audio arrives, and a stream the provider ends is reopened without waiting for sound.</li><li>An unreachable or slow provider held up everything else: stopping or quitting could take up to a minute while MeetCue retried, and audio was dropped meanwhile. Connecting now happens in the background, and every network step has a time limit.</li><li>Error messages now show what went wrong (for example <code>connection timed out</code>), connection errors disappear once recognition is back, and the panel marks a side whose recognition is reconnecting.</li><li>A setting the provider rejects is reported as <code>MC-ASR-004</code> instead of a network problem (<code>MC-ASR-002</code>), and isn&#39;t retried many times a second.</li><li>Connections no longer time out on networks where IPv6 is configured but doesn&#39;t work.</li></ul></li><li>The panel&#39;s level meters stayed flat until a session started, so the microphone looked dead in the panel while it worked in <strong>Settings › Audio</strong>. The visible panel now shows both levels before you press <strong>Start</strong>; nothing is sent anywhere until you do.</li><li>A microphone that delivers only silence (blocked in Windows privacy settings, or muted) is now reported with <code>MC-AUD-002</code>.</li><li>Unexpected errors inside MeetCue are now written to the log.</li></ul><h2 id="_0-1-3-—-2026-10-24" tabindex="-1">0.1.3 — 2026-10-24 <a class="header-anchor" href="#_0-1-3-—-2026-10-24" aria-label="Permalink to &quot;0.1.3 — 2026-10-24&quot;">​</a></h2><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Prices are read live from Anthropic&#39;s, Soniox&#39;s and Deepgram&#39;s official pricing pages, and from OpenAI-compatible servers that list prices with their models. Every current Claude model now shows its price and estimated cost; only a model with no price anywhere links to the pricing page.</li><li>Deepgram shows the rate billed today, including limited-time promotions, with the regular rate in the tooltip.</li><li>Changing a model, key, language or hint setting during a meeting takes effect right away: the next question uses the new models, and recognition switches without losing the sentence in progress.</li><li>Every setting can now be changed in the app: sliders for the voice threshold and end-of-sentence silence (now up to 3 s), panel layout and <strong>Reset panel position</strong> in <strong>General</strong>, <strong>Run setup again</strong>, all cost estimate assumptions, a list of your own prices with <strong>Remove</strong>, and the filler words counted in practice reviews. A new microphone or voice threshold also applies during a meeting.</li></ul><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Settings › Diagnostics › Activity log</strong> shows what MeetCue is doing as it happens: starting and pausing, whether audio arrives from each side, recognised sentences, questions and errors. Also in the tray menu, and from any error message.</li></ul><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Clicking <strong>Start</strong> or <strong>Resume</strong> when something was missing (a key, a model, the audio device) did nothing; the reason is now shown, and a session whose audio fails to start is no longer left half running.</li><li>Notices such as a shortcut that&#39;s already taken were never shown.</li><li>The meeting clock kept counting while paused.</li><li>The settings tab list scrolled away on long pages.</li><li>Speech recognition: <ul><li>The first sound of a sentence was often cut off; the 0.3 s before speech is now sent with it.</li><li>Recognition stopped for the rest of the meeting after a second connection drop, and after pausing for more than a few seconds; it now keeps the connection alive while paused and reconnects whenever needed.</li><li>With Deepgram, English sentences lost the spaces between their parts (&quot;yourexperience&quot;).</li><li>With Deepgram and both Chinese and English selected, English was sent to the Mandarin model. The first language in <strong>Meeting languages</strong> is now the main one, and there is a &quot;Mostly English, some Chinese&quot; choice.</li><li>The end-of-sentence silence setting was cut short at 0.8 s.</li></ul></li></ul><h2 id="_0-1-2-—-2026-10-24" tabindex="-1">0.1.2 — 2026-10-24 <a class="header-anchor" href="#_0-1-2-—-2026-10-24" aria-label="Permalink to &quot;0.1.2 — 2026-10-24&quot;">​</a></h2><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Prices are no longer built into the app. MeetCue downloads the <a href="/meetcue/reference/pricing">price reference</a>, checked against each provider&#39;s official pricing page, keeps the last copy for offline use, and can update it from <strong>Settings › Providers &amp; cost</strong>.</li><li>A more compact <strong>Models &amp; prices</strong> layout: one line per model with its price and estimated cost per hour, sorted by cost, with <strong>Cheapest</strong> and <strong>Fastest</strong> marked. API keys take one row per provider.</li><li>A model without a published price links to the provider&#39;s official pricing page instead of showing <strong>Price unknown</strong>.</li></ul><h3 id="fixed-6" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-6" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Deepgram Nova-3 used the multilingual rate. MeetCue requests one language for Chinese or English, which costs $0.0077 per minute.</li></ul><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Prices for Claude Sonnet 5, Claude Opus 5 and Claude Fable 5.1.</li></ul><h2 id="_0-1-1-—-2026-10-24" tabindex="-1">0.1.1 — 2026-10-24 <a class="header-anchor" href="#_0-1-1-—-2026-10-24" aria-label="Permalink to &quot;0.1.1 — 2026-10-24&quot;">​</a></h2><h3 id="fixed-7" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-7" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Deepgram, Anthropic and OpenAI-compatible keys failed verification and sessions using them would not start: only Soniox was wired up.</li><li>The setup window turned blank instead of closing when you clicked <strong>Finish</strong>.</li><li>Switches in Settings were drawn with the knob off-centre.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>Amazon Bedrock. Use Anthropic or an OpenAI-compatible API for hints.</li></ul><h2 id="_0-1-0-—-2026-10-23" tabindex="-1">0.1.0 — 2026-10-23 <a class="header-anchor" href="#_0-1-0-—-2026-10-23" aria-label="Permalink to &quot;0.1.0 — 2026-10-23&quot;">​</a></h2><h3 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Meeting mode: live question detection with early trigger, numbered talking points in about a second and a half, a question queue, and coverage ticks.</li><li>Floating panel that doesn&#39;t take focus, with full and mini layouts, click-through and hiding from screen sharing.</li><li>Speech recognition with Soniox and Deepgram; hints with Anthropic, Amazon Bedrock and OpenAI-compatible APIs.</li><li>Latency probe with endpoint selection, cost estimates and combination ranking.</li><li>Price table, usage tracking, budgets and CSV export.</li><li>Practice mode: subtitle and question-list import with preview editing, questions read aloud with system voices, real or simulated recognition, follow-up questions, four hint levels, and a review report with Markdown export.</li><li>Briefing material from txt, md, docx and pdf files.</li><li>English and Simplified Chinese interface and documentation.</li><li>Error codes with linked fixes, diagnostics export, <code>--demo</code> and <code>--self-test</code>.</li></ul>',58)])])}const p=t(n,[["render",s]]);export{g as __pageData,p as default};
